        return 0.0
    return electrons / volume

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    atoms = sum(occ)
    if atoms <= 0:
        return 0.0
    total = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            a = radii[i]
            b = radii[j]
            if occ[i] > 0 and occ[j] > 0 and a is not None and b is not None and a > 0 and b > 0:
                overlap = max(0.0, 1.0 - d / (a + b))
                total += occ[i] * occ[j] * overlap * overlap
    return 0.5 * total / atoms

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    edges = s.get('neighbors') or []
    total = 0.0
    first = 0.0
    second = 0.0
    for i in range(n):
        a = radii[i]
        if occ[i] > 0 and a is not None and a > 0:
            coordination = 0.0
            for edge in edges:
                if edge.get('i', -1) == i:
                    j = edge.get('j', -1)
                    d = edge.get('distance_A')
                    if 0 <= j < n and d is not None and d > 0:
                        b = radii[j]
                        if b is not None and b > 0:
                            x = d / (a + b)
                            x2 = x * x
                            coordination += occ[j] / (1.0 + x2 * x2 * x2)
            total += occ[i]
            first += occ[i] * coordination
            second += occ[i] * coordination * coordination
    if total <= 0:
        return 0.0
    mean = first / total
    return max(0.0, second / total - mean * mean)

def feature(s):
    if not s:
        return 0.0
    comp = s.get('composition') or {}
    fractions = [v for v in comp.values() if v is not None and v > 0]
    fraction_sum = sum(fractions)
    if fraction_sum <= 0:
        return 0.0
    expected = 1.0 - sum(v * v for v in fractions) / (fraction_sum * fraction_sum)
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    total = 0.0
    unlike = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0:
            a = radii[i]
            b = radii[j]
            if a is not None and b is not None and a > 0 and b > 0:
                x = d / (a + b)
                x2 = x * x
                w = occ[i] * occ[j] / (1.0 + x2 * x2 * x2)
                total += w
                if sites[i].get('element') != sites[j].get('element'):
                    unlike += w
    if total <= 0:
        return 0.0
    return unlike / total - expected

