def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    edges = s.get('neighbors') or []
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    total = 0.0
    result = 0.0
    for i in range(n):
        if occ[i] > 0:
            pairs = [(edge.get('distance_A'), occ[edge.get('j', -1)]) for edge in edges if edge.get('i', -1) == i and 0 <= edge.get('j', -1) < n and occ[edge.get('j', -1)] > 0 and edge.get('distance_A') is not None and edge.get('distance_A') > 0]
            if pairs:
                cutoff = 1.25 * min(d for d, o in pairs)
                weight = sum(o for d, o in pairs if d <= cutoff)
                if weight > 0:
                    mean = sum(o * d for d, o in pairs if d <= cutoff) / weight
                    variance = sum(o * (d / mean - 1.0) ** 2 for d, o in pairs if d <= cutoff) / weight
                    total += occ[i]
                    result += occ[i] * variance
    if total <= 0:
        return 0.0
    return result / total

def feature(s):
    if not s:
        return 0.0
    sites = s.get('sites') or []
    props = s.get('element_properties') or {}
    edges = s.get('neighbors') or []
    n = len(sites)
    occ = [max(0.0, t.get('occupancy', 1.0) or 0.0) for t in sites]
    radii = [(props.get(t.get('element')) or {}).get('covalent_radius_A') for t in sites]
    en = [(props.get(t.get('element')) or {}).get('eneg') for t in sites]
    total = 0.0
    result = 0.0
    for i in range(n):
        a = radii[i]
        if occ[i] > 0 and a is not None and a > 0 and en[i] is not None:
            weight = 0.0
            neighbor_en = 0.0
            for edge in edges:
                if edge.get('i', -1) == i:
                    j = edge.get('j', -1)
                    d = edge.get('distance_A')
                    if 0 <= j < n and occ[j] > 0 and d is not None and d > 0:
                        b = radii[j]
                        if b is not None and b > 0 and en[j] is not None:
                            x = d / (a + b)
                            x2 = x * x
                            w = occ[j] / (1.0 + x2 * x2 * x2)
                            weight += w
                            neighbor_en += w * en[j]
            if weight > 0:
                delta = en[i] - neighbor_en / weight
                total += occ[i]
                result += occ[i] * delta * delta
    if total <= 0:
        return 0.0
    return result / total
